338	// ── Start ───────────────────────────────────────────────────────
339	
340	fn start() -> Result<()> {
341	    match detected_service_manager()? {
342	        ServiceManager::Launchd => {
343	            let plist = macos_plist_path()?;
344	            if !plist.exists() {
345	                bail!("Service not installed. Run `ironclaw service install` first.");
346	            }
347	            run_checked(Command::new("launchctl").arg("load").arg("-w").arg(&plist))?;
348	            run_checked(Command::new("launchctl").arg("start").arg(SERVICE_LABEL))?;
349	            println!("Service started");
350	            Ok(())
351	        }
352	        ServiceManager::SystemdUser => {
353	            run_checked(Command::new("systemctl").args(["--user", "daemon-reload"]))?;
354	            if linux_xmpp_bridge_unit_path()?.exists() {
355	                run_checked(Command::new("systemctl").args([
356	                    "--user",
357	                    "start",
358	                    SYSTEMD_XMPP_BRIDGE_UNIT,
359	                ]))
360	                .ok();
361	            }
362	            run_checked(Command::new("systemctl").args(["--user", "start", SYSTEMD_UNIT]))?;
363	            println!("Service started");
364	            Ok(())
365	        }
366	        ServiceManager::OpenRc => start_linux_openrc(),
367	    }
368	}
369	
370	// ── Stop ────────────────────────────────────────────────────────
371	
372	fn stop() -> Result<()> {
373	    match detected_service_manager()? {
374	        ServiceManager::Launchd => {
375	            let plist = macos_plist_path()?;
376	            run_checked(Command::new("launchctl").arg("stop").arg(SERVICE_LABEL)).ok();
377	            run_checked(
378	                Command::new("launchctl")
379	                    .arg("unload")
380	                    .arg("-w")
381	                    .arg(&plist),
382	            )
383	            .ok();
384	            println!("Service stopped");
385	            Ok(())
386	        }
387	        ServiceManager::SystemdUser => {
388	            run_checked(Command::new("systemctl").args(["--user", "stop", SYSTEMD_UNIT])).ok();
389	            if linux_xmpp_bridge_unit_path()?.exists() {
390	                run_checked(Command::new("systemctl").args([
391	                    "--user",
392	                    "stop",
393	                    SYSTEMD_XMPP_BRIDGE_UNIT,
394	                ]))
395	                .ok();
396	            }
397	            println!("Service stopped");
398	            Ok(())
399	        }
400	        ServiceManager::OpenRc => stop_linux_openrc(),
401	    }
402	}
403	
404	// ── Status ──────────────────────────────────────────────────────
405	
406	fn status() -> Result<()> {
407	    match detected_service_manager()? {
408	        ServiceManager::Launchd => {
409	            let out = run_capture(Command::new("launchctl").arg("list"))?;
410	            let running = out.lines().any(|line| line.contains(SERVICE_LABEL));
411	            println!(
412	                "Service: {}",
413	                if running {
414	                    "running/loaded"
415	                } else {
416	                    "not loaded"
417	                }
418	            );
419	            println!("Unit: {}", macos_plist_path()?.display());
420	            Ok(())
421	        }
422	        ServiceManager::SystemdUser => {
423	            let state =
424	                run_capture(Command::new("systemctl").args(["--user", "is-active", SYSTEMD_UNIT]))
425	                    .unwrap_or_else(|_| "unknown".into());
426	            println!("Service state: {}", state.trim());
427	            println!("Unit: {}", linux_unit_path()?.display());
428	            let bridge_file = linux_xmpp_bridge_unit_path()?;
429	            if bridge_file.exists() {
430	                let bridge_state = run_capture(Command::new("systemctl").args([
431	                    "--user",
432	                    "is-active",
433	                    SYSTEMD_XMPP_BRIDGE_UNIT,
434	                ]))
435	                .unwrap_or_else(|_| "unknown".into());
436	                println!("XMPP bridge state: {}", bridge_state.trim());
437	                println!("XMPP bridge unit: {}", bridge_file.display());
438	            }
439	            Ok(())
440	        }
441	        ServiceManager::OpenRc => status_linux_openrc(),
442	    }
443	}
