445	// ── Uninstall ───────────────────────────────────────────────────
446	
447	fn uninstall() -> Result<()> {
448	    // Stop first (ignore errors, service might not be running)
449	    stop().ok();
450	
451	    match detected_service_manager()? {
452	        ServiceManager::Launchd => {
453	            let file = macos_plist_path()?;
454	            if file.exists() {
455	                std::fs::remove_file(&file)
456	                    .with_context(|| format!("failed to remove {}", file.display()))?;
457	            }
458	            println!("Service uninstalled ({})", file.display());
459	            Ok(())
460	        }
461	        ServiceManager::SystemdUser => uninstall_linux_systemd_user(),
462	        ServiceManager::OpenRc => uninstall_linux_openrc(),
463	    }
464	}
