582	fn linux_unit_content(exe: &Path, include_xmpp_bridge: bool) -> String {
583	    let bridge_unit_lines = if include_xmpp_bridge {
584	        format!(
585	            "Wants={bridge}\n\
586	             After=network.target {bridge}\n",
587	            bridge = SYSTEMD_XMPP_BRIDGE_UNIT
588	        )
589	    } else {
590	        "After=network.target\n".to_string()
591	    };
592	
593	    format!(
594	        "[Unit]\n\
595	         Description=LunarWing daemon\n\
596	         {bridge_unit_lines}\
597	         \n\
598	         [Service]\n\
599	         Type=simple\n\
600	         # Disable interactive CLI/REPL in daemon mode to prevent blocking on stdin\n\
601	         Environment=\"CLI_ENABLED=false\"\n\
602	         Environment=\"AGENT_NAME=lunarwing\"\n\
603	         Environment=\"ALLOW_PRIVATE_IPS=1\"\n\
604	         Environment=\"PGSSLMODE=disable\"\n\
605	         ExecStart=\"{exe}\" run\n\
606	         Restart=always\n\
607	         RestartSec=3\n\
608	         \n\
609	         [Install]\n\
610	         WantedBy=default.target\n",
611	        exe = exe.display(),
612	        bridge_unit_lines = bridge_unit_lines,
613	    )
614	}
615	
616	fn linux_xmpp_bridge_unit_content(exe: &Path) -> String {
617	    format!(
618	        "[Unit]\n\
619	         Description=LunarWing XMPP bridge\n\
620	         After=network.target\n\
621	         PartOf={main_unit}\n\
622	         \n\
623	         [Service]\n\
624	         Type=simple\n\
625	         ExecStart=\"{exe}\"\n\
626	         Restart=always\n\
